import{_ as t,o as r,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"双向绑定的方式","description":"传统方式： 定义属性，定义ｅｍｉｔ，定义可写状态 然后ｗａｔｃｈ属性的变化，更新内部可写状态； 同时ｗａｔｃｈ内部状态的变化，当变化时，通过调用ｅｍｉｔ通知外部 计算属性： 封装更好．同样定义属性和ｅｍｉｔ 定义计算属性ｇｅｔ，ｓｅｔ，ｇｅｔ从ｐｒｏｐｓ直接衍生出新值； ｓｅｔ函。","frontmatter":{"title":"双向绑定的方式","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"传统方式： 定义属性，定义ｅｍｉｔ，定义可写状态 然后ｗａｔｃｈ属性的变化，更新内部可写状态； 同时ｗａｔｃｈ内部状态的变化，当变化时，通过调用ｅｍｉｔ通知外部 计算属性： 封装更好．同样定义属性和ｅｍｉｔ 定义计算属性ｇｅｔ，ｓｅｔ，ｇｅｔ从ｐｒｏｐｓ直接衍生出新值； ｓｅｔ函。","sidebarWeight":129,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/双向绑定/双向绑定的方式.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/双向绑定的方式.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/双向绑定的方式.md"}'),l={name:"posts/Vue系统教程/03-响应式与组合式 API/双向绑定的方式.md"};function n(i,e,g,a,u,d){return r(),o("div",null,[...e[0]||(e[0]=[s('<div><h1 id="双向绑定的方式" tabindex="-1">双向绑定的方式 <a class="header-anchor" href="#双向绑定的方式" aria-label="Permalink to &quot;双向绑定的方式&quot;">​</a></h1><blockquote><p>本节目标：理解“双向绑定的方式”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><ul><li>传统方式： <ul><li>定义属性，定义ｅｍｉｔ，定义可写状态</li><li>然后ｗａｔｃｈ属性的变化，更新内部可写状态；</li><li>同时ｗａｔｃｈ内部状态的变化，当变化时，通过调用ｅｍｉｔ通知外部</li></ul></li><li>计算属性： <ul><li>封装更好．同样定义属性和ｅｍｉｔ</li><li>定义计算属性ｇｅｔ，ｓｅｔ，ｇｅｔ从ｐｒｏｐｓ直接衍生出新值；</li><li>ｓｅｔ函数是当值变更时，调用ｅｍｉｔ，好处是将更新函数和获取函数写在了一起</li></ul></li><li>ｄｅｆｉｎｅＭｏｄｅｌ：语法糖 <ul><li>不用定义属性和ｅｍｉｔ</li><li>当ｐｒｏｐｓ的对应属性变化时自动更新</li><li>当值被修改时自动会触发ｅｍｉｔ通知外部</li><li>代码最简洁封装最好，但有内外初始值不一致的问题</li></ul></li></ul><p>ａｉ调整版本</p><ol><li>传统“prop + emit + 本地可写状态 + 双向 watch”的方式</li></ol><p>这是历史兼容的做法，但<strong>易引入复杂度与循环更新</strong>（外部变 -&gt; 内部 watch；内部变 -&gt; 外部 emit，再触发外部回流），维护成本高，应尽量避免作为默认方案。仅在<strong>必须维护与外部值“脱钩的临时状态”</strong>（如防抖输入、复杂表单草稿）时再考虑。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a> 4. “计算属性 getter/setter”封装</p><p>适合作为过渡与低成本封装：<strong>get 只做纯派生</strong>（不可产生副作用），<strong>set 只负责对外同步</strong>。不要在 getter 里发请求、改状态或做副作用逻辑；必要的值转换放在 setter 或更推荐放到 v-model 修饰符的语义层。<a href="https://vuejs.org/guide/essentials/computed?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Vue.js+1</a> 7. defineModel（推荐，Vue 3.4+） 8. <strong>官方推荐的标准解法</strong>：更少样板代码，天然与 v-model 对齐；返回的是一个可写 ref，既能读外部也能写回外部；绑定原生表单控件更直接。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a> 9. <strong>多路模型</strong>：支持<strong>多个 v-model: 目标</strong>（如 v-model:title / v-model:visible），各自独立同步，避免自定义事件名分散。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a> 10. <strong>修饰符与变换器</strong>：不仅能拿到 .trim/.number/.lazy 等修饰符，还可用 get/set <strong>集中做读/写时的值转换</strong>（例如大小写规范化、去空格），让转换归位到“模型层”，降低组件内部 watch/计算的负担。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a> 11. <strong>类型与选项</strong>：可声明必填/默认值/类型，TypeScript 友好。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a></p><p>==你提到的“==<strong>内外初始值不一致</strong>==”——确实是重点坑==</p><ul><li>==把默认值==<strong>下放到父级</strong>==（从源头提供），或在子级把模型标记为==<strong>必填</strong>==以强制父级传值；==</li><li>==若业务上必须在子级兜底，则在父级初始化阶段显式接管这份默认值（保持源头一致），而不是仅在子里设默认。====Vue.js+1==</li></ul><p><strong>官方明确警示</strong>==：若在子组件用 defineModel({ default: ... }) 设置默认值、而父组件未提供初值，会出现==<strong>子真有值、父仍是 undefined的去同步</strong>==。解决思路：==</p><p>变更语义与对象可变性</p><ul><li>Vue 传引用：当模型值是<strong>对象/数组</strong>时，直接在子里深层改属性会<strong>绕过预期的“发出变更意图”语义（看起来“没 emit 也变了”）。最佳实践是：将变更语义放在模型写入路径（set/emit），必要时拷贝后再写回</strong>，让外部感知一次“原子变更”。（这一点是 v-model 模式设计的初衷）<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js+1</a></li></ul><ol><li>何时仍然需要本地可写副本 / watch</li><li>当组件内部需要<strong>阶段性脱钩</strong>（如输入法合成、草稿态、多步编辑、延迟校验）或要处理<strong>跨源头合成值</strong>时，可以保留局部状态，但应<strong>以 defineModel 为“单一事实来源”</strong>：内部完成后，再一次性写回模型，减少来回抖动与多处监听。<a href="https://vuejs.org/guide/components/v-model" target="_blank" rel="noreferrer">Vue.js</a> 4. 迁移与兼容要点</li><li>Vue 3 中自定义组件的 v-model 语义已统一为：<strong>prop modelValue + 事件 update:modelValue</strong>；支持<strong>多个 v-model与自定义修饰符</strong>。老项目迁移要注意这一断点变化，避免旧式 .sync 与 value/input 约定混用。<a href="https://v3-migration.vuejs.org/breaking-changes/v-model?utm_source=chatgpt.com" target="_blank" rel="noreferrer">Vue 3 迁移指南</a></li></ol><p><strong>精简结论</strong></p><ul><li><strong>默认首选 defineModel</strong>：配合修饰符与 get/set 变换，集中处理读写与校验。</li><li><strong>避免“双向 watch”样式</strong>的传统同步；确需临时脱钩再用局部状态。</li><li><strong>初值一致性由父级负责</strong>，别在子里单独给默认值导致去同步。</li><li><strong>对象模型走“写回”语义</strong>（必要时拷贝），不要默默深改引用。</li></ul></div>',1)])])}const c=t(l,[["render",n]]);export{m as __pageData,c as default};
